<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, auth, paths, displayDate } from '../api'
const posts = ref([]), mine = ref([]), error = ref(''), message = ref(''), busy = ref(false), composing = ref(false)
const form = reactive({ title: '', body: '', graduation_year: 2025, city: '衡阳', path: 'employment', public_consent: false })
const statuses = { pending: '待审核', approved: '已发布', rejected: '未通过', withdrawn: '已撤回' }
async function load() { try { posts.value = await api('/experiences'); if(auth.user) mine.value = await api('/experiences/mine') } catch(e) { error.value = e.message } }
async function submit() {
  busy.value = true; error.value = ''; message.value = ''
  try { await api('/experiences', { method: 'POST', body: form }); composing.value = false; form.title = ''; form.body = ''; form.public_consent = false; message.value = '经验已提交，管理员审核通过后公开。'; await load() }
  catch(e) { error.value = e.message } finally { busy.value = false }
}
async function withdraw(post) { try { await api(`/experiences/${post.id}`, { method: 'DELETE' }); message.value = '该经验已撤回。'; await load() } catch(e) { error.value = e.message } }
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">ALUMNI STORIES</div><h1>听见走过这条路的人<span class="heading-dot">.</span></h1><p>自愿分享，经审核公开。个人经历提供参考，不承诺同样的结果。</p></div><button v-if="auth.user" class="button" @click="composing = !composing">分享我的经验 ↗</button><RouterLink v-else class="button" to="/login">登录后分享</RouterLink></div><div v-if="error" class="alert error">{{ error }}</div><div v-if="message" class="alert success">{{ message }}</div><form v-if="composing && auth.user" class="panel profile-form" @submit.prevent="submit"><h2>写下你的经验</h2><label>标题<input v-model="form.title" required minlength="2" maxlength="150"></label><div class="form-grid"><label>毕业届次<input v-model.number="form.graduation_year" type="number" min="2000" max="2100" required></label><label>城市<input v-model="form.city" required maxlength="80"></label><label>实际路径<select v-model="form.path"><option v-for="p in ['employment','postgraduate','civil_service','public_institution','unresolved','other']" :key="p" :value="p">{{ paths[p] }}</option></select></label></div><label>经验内容<textarea v-model="form.body" rows="6" minlength="20" maxlength="10000" required placeholder="分享准备过程、踩过的坑与建议，请勿包含他人联系方式或隐私。"></textarea></label><label class="choice"><input v-model="form.public_consent" type="checkbox" required>同意以当前公开昵称发布这篇经验，并可随时撤回</label><button class="button" :disabled="busy">{{ busy ? '提交中…' : '提交审核' }}</button></form><section v-if="mine.length" class="panel"><h2>我的分享</h2><div v-for="p in mine" :key="p.id" class="opportunity-row"><div><h3>{{ p.title }}</h3><p>{{ p.moderation_note || '审核记录将显示在这里' }}</p></div><span class="tag">{{ statuses[p.status] }}</span><button v-if="p.status !== 'withdrawn'" class="ghost" @click="withdraw(p)">撤回</button></div></section><div v-if="!posts.length" class="empty large"><span>☷</span><h3>第一份经验，等待你来分享</h3><p>暂无经审核且获得公开授权的校友经验。</p></div><article v-for="p in posts" :key="p.id" class="panel experience-card"><div class="panel-heading"><span class="tag">{{ paths[p.path] }}</span><span class="muted">自报经历 · {{ displayDate(p.created_at) }}</span></div><h2>{{ p.title }}</h2><p class="muted">{{ p.public_nickname }} · {{ p.graduation_year }} 届 · {{ p.city }}</p><p class="post-body">{{ p.body }}</p></article></template>
